INSERT INTO risk_assessments (store_id, model_version, risk_score, risk_level, location_risk_score, classification_detail, main_reason, prediction, recommended_action, assessed_at) VALUES (1000, 'closure-risk-v1-v2-2026-08', 11.81, 1, NULL, '업종 기준만 판단 — 입지 정보 없음(서울 외 지역 매장)', '같은 업종의 다른 브랜드들도 최근 해지가 잦음(업종 평균 해지율 15.8%) 방향 확인 필요: 배경표본 대비 43백분위로 \'낮음\' 쪽인데, 이 카테고리는 통상 \'높을수록\' 위험하다고 가정함 — 실제 관계가 비선형일 수 있으니 조항 적용 전 근거를 다시 확인할 것', '모델 비교군 기준 위험 백분위 11.8%로 분류되었습니다.', '업종 트렌드 정기 모니터링, 업종 내 수요변화 조기경보, 업종 전환 상담 제공', NOW());
