  (LAST_INSERT_ID(), 'closure-risk-v1-v2-2026-08', 3, 'trdar_chnge_ix', '상권 쇠퇴 추세', 0.25380788219257394, '상권변화등급 HH', '침체 지역 매장 우선 지원(마케팅/리뉴얼)', '상권 등급 재평가 결과를 갱신조건에 연동하는 조항을 검토한다.');
