  (LAST_INSERT_ID(), 'closure-risk-v1-v2-2026-08', 2, 'avg_selng_amt_per_store', '상권 매출 침체', 0.38077592745236655, '상권 매출 침체 관련 값이 이 브랜드/매장에 결측 — 모델은 결측을 반영해 판단했으나 구체적 수치는 근거로 제시할 수 없음', '매출 모니터링 주기 단축, 조기 개입', '성과 기반 갱신조건(최소 매출 기준)을 명시한다.'),
  (LAST_INSERT_ID(), 'closure-risk-v1-v2-2026-08', 3, 'avg_competitors_250m', '경쟁밀도', 0.1343302908580408, '반경 250m 내 동일업종 경쟁점포 11개 방향 확인 필요: 배경표본 대비 48백분위로 \'낮음\' 쪽인데, 이 카테고리는 통상 \'높을수록\' 위험하다고 가정함 — 실제 관계가 비선형일 수 있으니 조항 적용 전 근거를 다시 확인할 것', '경쟁 밀집 지역 가맹점 대상 포지셔닝 차별화 지원, 신규 출점 시 경쟁밀도 사전 검토', '반경 내 동일업종 신규 출점 제한(상권보호) 조항을 강화하고, 경쟁밀도 급변 시 갱신조건을 재검토한다.');
INSERT INTO risk_assessments (store_id, model_version, risk_score, risk_level, location_risk_score, classification_detail, main_reason, prediction, recommended_action, assessed_at) VALUES (1154, 'closure-risk-v1-v2-2026-08', 79.45, 4, 79.45, '입지 위험 — 업종은 괜찮으나 이 매장 입지가 나쁨 (상권/접근성 개선 조치)', '상권 매출 침체 관련 값이 이 브랜드/매장에 결측 — 모델은 결측을 반영해 판단했으나 구체적 수치는 근거로 제시할 수 없음', '모델 비교군 기준 위험 백분위 79.5%로 분류되었습니다.', '매출 모니터링 주기 단축, 조기 개입', NOW());
