INSERT INTO risk_assessments (store_id, model_version, risk_score, risk_level, location_risk_score, classification_detail, main_reason, prediction, recommended_action, assessed_at) VALUES (1176, 'closure-risk-v1-v2-2026-08', 79.68, 4, 79.68, '입지 위험 — 업종은 괜찮으나 이 매장 입지가 나쁨 (상권/접근성 개선 조치)', '그 상권의 폐업 평균 영업개월이 서울 평균 대비 +19.0개월 차이 방향 확인 필요: 배경표본 대비 99백분위로 \'높음\' 쪽인데, 이 카테고리는 통상 \'낮을수록\' 위험하다고 가정함 — 실제 관계가 비선형일 수 있으니 조항 적용 전 근거를 다시 확인할 것', '모델 비교군 기준 위험 백분위 79.7%로 분류되었습니다.', '침체 지역 매장 우선 지원(마케팅/리뉴얼), 상권 등급 재평가', NOW());
